import { expect, type Page } from "@playwright/test";

export const getLocators = (page: Page) => {
  const sidePanel = page.getByTestId("inspector-side-panel");
  const flowTimeline = page.getByTestId("flow-timeline").or(sidePanel.getByTestId("flow-timeline"));
  const flowTimelineItems = flowTimeline.getByTestId("flow-timeline-item");

  return {
    flowTimeline,
    flowTimelineItems,
    flowTimelineItemByName: (name: string) => flowTimelineItems.filter({ hasText: name }),
    flowTimelineItemByNameAndStatus: (name: string, status: string) =>
      flowTimelineItems.filter({ hasText: name }).filter({ hasText: status }),
    historyPlaceholder: page.getByText("Conversation history will be shown here."),
  };
};

export const actions = (page: Page) => {
  const locators = getLocators(page);

  return {
    clickItem: async (flowName: string) => {
      await locators.flowTimelineItemByName(flowName).click();
    },
  };
};

export const assertions = (page: Page) => {
  const locators = getLocators(page);

  return {
    placeholderIsVisible: async () => {
      await expect(
        locators.historyPlaceholder,
        "Conversation history placeholder should be visible",
      ).toBeVisible();
    },
    timelineIsVisible: async (options?: { timeout?: number }) => {
      await expect(
        locators.flowTimeline,
        "Conversation history timeline should be visible",
      ).toBeVisible({ timeout: options?.timeout ?? 10000 });
    },
    timelineIsHidden: async () => {
      await expect(
        locators.flowTimeline,
        "Conversation history timeline should be hidden",
      ).toBeHidden();
    },
    itemCountIs: async (count: number) => {
      await expect(
        locators.flowTimelineItems,
        `Conversation history timeline should have ${count} entries`,
      ).toHaveCount(count, { timeout: 10000 });
    },
    itemIsVisible: async (flowName: string) => {
      await expect(
        locators.flowTimelineItemByName(flowName).first(),
        `Conversation history timeline should include "${flowName}"`,
      ).toBeVisible({ timeout: 10000 });
    },
    itemIsHidden: async (flowName: string) => {
      await expect(
        locators.flowTimelineItemByName(flowName),
        `Conversation history timeline should not include "${flowName}"`,
      ).toBeHidden({ timeout: 10000 });
    },
    itemHasStatus: async (flowName: string, status: string) => {
      await expect(
        locators.flowTimelineItemByNameAndStatus(flowName, status),
        `Conversation history timeline entry "${flowName}" should show "${status}"`,
      ).toBeVisible({ timeout: 10000 });
    },
  };
};
